contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Drive the contract: deposit an initial value (maybe zero) then deposit a second value `val`.
    // The rule: after calling Put with value `val`, the stored balance increases by exactly `val`.
    function run(uint initUnlock, uint initVal, uint val) public payable {
        // ensure this contract has enough balance to send the two deposits
        require(address(this).balance >= initVal + val);

        // record balance before any action
        uint before = c.Acc(address(this)).balance;

        // First deposit: may be zero or nonzero. On original contract P this is allowed even if zero.
        c.Put{value: initVal}(initUnlock);

        // read intermediate balance
        uint mid = c.Acc(address(this)).balance;

        // Second deposit: the distinguishing call whose behavior differs between P and M
        c.Put{value: val}(initUnlock);

        // read after
        uint after = c.Acc(address(this)).balance;

        // The invariant: the net increase from before to after equals initVal + val
        // Equivalent to: after == before + initVal + val
        assert(after == before + initVal + val);
    }

    // allow receiving ether so the test contract can be funded externally
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint unlockTime, uint value) public payable {
        require(address(this).balance >= value);
        bool reverted;
        try c.Put{value: value}(unlockTime) { reverted = false; } catch { reverted = true; }
        // On original contract P, Put never reverts for any value (including 0).
        // So assert that reverted is false for all input values; mutant M that forbids zero-value deposits will violate this when value == 0.
        assert(reverted == false);
    }
    receive() external payable { }
}

