pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint64 deposit, uint64 uts) public {
        // keep wide but sensible bounds: deposit at least 1 wei and not overflowing; uts any uint64 mapped into uint
        vm.assume(actor != address(0));
        uint256 amt = bound(deposit, 1, 10 ether);
        uint256 unlock = uint256(uts);

        // fund actor and call Put as that actor with fuzzed params
        vm.deal(actor, amt);
        vm.prank(actor);
        c.Put{value: amt}(unlock);

        // The universal property: reference implementation always records unlockTime >= block.timestamp
        // We read the public mapping Acc via autogenerated getter: Acc(address) returns (unlockTime, balance)
        (uint256 recordedUnlock,,) = _readAcc(actor);

        // single assertion: recorded unlockTime is at least current block.timestamp
        assertTrue(recordedUnlock >= block.timestamp);
    }

    // helper to call the public getter; solidity autogenerated getter for mapping of struct returns tuple (unlockTime, balance)
    function _readAcc(address a) internal view returns (uint256, uint256, address) {
        // The mapping is public: Acc(address) returns (uint,uint). However the contract C may have different return ordering depending on source;
        // We call the getter via low-level staticcall to obtain the first uint (unlockTime) and second (balance).
        // Build selector for Acc(address) which is generated as Acc(address) -> function selector
        bytes memory payload = abi.encodeWithSignature("Acc(address)", a);
        (bool ok, bytes memory ret) = address(c).staticcall(payload);
        require(ok, "getter failed");
        // decode two uints
        (uint256 u, uint256 b) = abi.decode(ret, (uint256, uint256));
        return (u, b, a);
    }
}

