pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: actor address and amount to deposit and an unlockTime
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        // keep actor non-zero
        vm.assume(actor != address(0));
        // bound amount to a reasonable range to avoid overflow in vm.deal and to ensure it's >= 1 wei
        amount = bound(amount, 1, 1 ether * 1000);
        // bound unlockTime to a future-ish timestamp but keep wide
        unlockTime = bound(unlockTime, block.timestamp, block.timestamp + 365 days);

        // Fund the actor so it can send value
        vm.deal(actor, amount + 1 ether);

        // record prior balance via the public getter Acc(actor).balance
        // The auto-generated getter for mapping (address => Holder) returns (uint unlockTime, uint balance) in newer compilers,
        // but to be safe we will read the public mapping by calling c.Acc(actor) and reading the second returned value.
        (uint priorUnlock, uint priorBal) = c.Acc(actor);

        // Make the actor call Put with the fuzzed amount and unlockTime
        vm.prank(actor);
        // call is payable
        try c.Put{value: amount}(unlockTime) {
            // succeeded
        } catch {
            // If Put reverts for some inputs (shouldn't in reference for these bounds), treat as failing call
            // but we still assert the property using the contract's visible state after the attempted call
        }

        // Read post-call balance
        (, uint postBal) = c.Acc(actor);

        // The general correct rule: after a successful Put the stored balance must be at least priorBal + amount
        // (the reference increases by msg.value; the mutant overwrites with msg.value which can make it smaller)
        // We assert that postBal >= priorBal + amount
        // Note: use assertTrue to read c's public state as required
        assertTrue(postBal >= priorBal + amount);
    }
}

