pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 deposit, uint256 priorDeposit) public {
        // keep wide domain but ensure reasonable ether bounds
        deposit = bound(deposit, 0, 10 ether);
        priorDeposit = bound(priorDeposit, 0, 10 ether);
        vm.assume(actor != address(0));

        // Fund actor so it can send deposit
        vm.deal(actor, deposit + priorDeposit + 1 ether);

        // If priorDeposit > 0 we simulate that actor already had made a prior Put
        if (priorDeposit > 0) {
            vm.startPrank(actor);
            c.Put{value: priorDeposit}(0);
            vm.stopPrank();
        }

        // Read prior balance from the contract's public mapping getter
        uint256 before = c.Acc(actor).balance;

        // Now perform the tested Put with deposit
        vm.startPrank(actor);
        c.Put{value: deposit}(0);
        vm.stopPrank();

        // Exactly one assertion: the new stored balance is at least the previous stored balance
        // (This is true for the reference which adds msg.value, but false for the mutant that overwrites)
        uint256 after = c.Acc(actor).balance;
        assertTrue(after >= before);
    }
}

