pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: two addresses and two amounts
    function testFuzz_property(address a1, address a2, uint256 v1, uint256 v2) public {
        // keep addresses distinct and nonzero
        vm.assume(a1 != address(0));
        vm.assume(a2 != address(0));
        vm.assume(a1 != a2);
        // bound amounts to reasonable range and ensure at least 1 wei (allowed wide)
        v1 = bound(v1, 1, 1 ether * 1000);
        v2 = bound(v2, 1, 1 ether * 1000);

        // ensure both callers start with zero recorded balance in c
        // they are fresh addresses so Acc[...] should be zero; just to be safe we don't pre-fund c for them
        // Fund the addresses externally so they can send ETH
        vm.deal(a1, v1);
        vm.deal(a2, v2);

        // a1 deposits v1
        vm.prank(a1);
        c.Put{value: v1}(0);

        // a2 deposits v2
        vm.prank(a2);
        c.Put{value: v2}(0);

        // The general rule: for callers that started with zero balance, after their deposit their recorded balance equals the deposited amount.
        // Read balances via public getter Acc(address).balance -> autogenerated struct getter: Acc(addr).balance is accessible as (uint,uint) tuple in solidity?
        // The mapping to struct yields a tuple (unlockTime, balance) via the auto getter; call it accordingly.
        (uint ut1, uint bal1) = c.Acc(a1);
        (uint ut2, uint bal2) = c.Acc(a2);

        // single assertion: both balances equal their respective deposit amounts
        assertTrue(bal1 == v1 && bal2 == v2);
    }
}

