import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed params: sender address and amount of ether to send
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount within a reasonable range so vm.deal can supply it
        amount = bound(amount, 0, 10 ether);
        // the property: after calling Put, the last Log message's Data must be "Put"

        // prepare sender with funds and make the call as sender
        vm.deal(sender, amount);
        vm.prank(sender);
        // perform the payable call; Put is public, so call with value
        c.Put{value: amount}(block.timestamp + 1);

        // read the last Log message via the auto-generated getters
        // LogFile is public in C, so c.LogFile() returns the Log contract address
        address logAddr = c.LogFile();
        // The Log contract exposes History(uint) public getter and History.length public getter
        // get length
        uint len = Log(logAddr).HistoryLength();
        // ensure there's at least one message; reference always pushes one on Put
        assertTrue(len > 0);
        // fetch last message's Data
        (address s, string memory data, uint v, uint t) = Log(logAddr).History(len - 1);

        // single assertion: data must equal "Put"
        assertTrue(keccak256(bytes(data)) == keccak256(bytes("Put")));
    }
}

// Minimal interfaces / helpers matching the Log contract's public getters
contract Log {
    // mirror the Message tuple returned by History(uint)
    function History(uint) public view returns (address, string memory, uint, uint) {}
    // getter for History.length
    function HistoryLength() public view returns (uint) {}
}

