pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address actor, uint256 unlockTime, uint256 value) public {
        // keep value in a sensible range so vm.deal won't overflow and the contract MinSum logic is reachable
        value = bound(value, 0, 5 ether);
        // actor should not be zero address for sensible log sender
        vm.assume(actor != address(0));

        // fund the actor so they can send value
        vm.deal(actor, value);
        vm.prank(actor);
        bool ok;
        try c.Put{value: value}(unlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always succeeds (ok==true) for all inputs where payable transfer semantics and require pass.
        // The mutant does not change success behaviour of Put itself; the distinguishing observable is the Log's Last message data.
        // Read the Log contract through auto-generated getter: Log contract deployed at address provided in constructor (this test used address(this)).
        // The Log in reference is this (the test contract) so we can inspect its History via the public array getter.
        // The reference implementation always recorded the string "Put" as the last message Data after a successful Put.

        // Build a call to the Log.History public getter: History takes an index and returns (Sender, Data, Val, Time).
        // Since the test contract is used as Log, implement that getter here and rely on c.Acc to have been updated.
        // However, we must observe c only via its public surface: C has public LogFile; but C.LogFile() is not present as a function in C's interface
        // Instead, the deployed C in setUp points LogFile to address(this), so we can read this contract's recorded History array maintained below.

        // Assertion: if Put succeeded (ok==true) then the last recorded History entry's Data equals "Put".
        // We emulate the Log.AddMessage behavior in this test contract itself because C was constructed with address(this) as log.

        // If Put succeeded, there must be at least one History entry recorded by this contract.
        if (ok) {
            // read last index
            uint len = HistoryLength();
            // ensure there is at least one entry
            assertTrue(len > 0);
            // read last message Data and assert it equals "Put"
            (address s, string memory d, uint v, uint t) = History(len - 1);
            // single assertion about C's observable behavior: that the last log Data equals "Put"
            // We assert true iff d equals "Put"
            assertTrue(keccak256(bytes(d)) == keccak256(bytes("Put")));
        } else {
            // If Put reverted, then for the reference behavior this can only happen when require fails (e.g., overflow),
            // still the reference never records a different tag vs mutant for successful paths; we simply assert that revert is allowed.
            // To satisfy the single-assert rule in this branch, assert that ok==false implies no new history entry was added.
            uint len = HistoryLength();
            // If Put reverted, it should not have recorded a Log entry; assert that length is 0 in that case.
            // (This is consistent with reference since AddMessage is only called after state update and not on revert.)
            assertTrue(len == 0);
        }
    }

    // The following implements the Log contract interface so that C(address(this)) works as the LogFile.
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    // auto-generated getter mimic for History length
    function HistoryLength() public view returns (uint) { return History.length; }
    // public getter for History element (matches the Log contract's public array getter signature)
    function History(uint i) public view returns (address, string memory, uint, uint) {
        Message storage m = History[i];
        return (m.Sender, m.Data, m.Val, m.Time);
    }
}

