    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzz parameters: actor address and amount to deposit/withdraw, and an unlockTime offset
    function testFuzz_property(address actor, uint256 depositAmt, uint256 withdrawAmt, uint256 offset) public {
        // keep domain reasonable and wide
        vm.assume(actor != address(0));
        // ensure amounts are within 1e30 to avoid overflow in test harness
        depositAmt = bound(depositAmt, 1 wei, 10 ether);
        withdrawAmt = bound(withdrawAmt, 1 wei, 10 ether);
        // ensure MinSum is 1 ether in contract; we want deposit >= MinSum to be potentially true
        // allow offset to be small so we can set unlockTime near current block
        offset = bound(offset, 0, 100);

        // actor deposits depositAmt to reach balance; use fallback/Put by calling Put directly
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Put{value: depositAmt}(block.timestamp + offset + 1); // set unlockTime at now + offset + 1

        // ensure the holder balance in contract is >= MinSum and >= withdrawAmt; otherwise Collect will be no-op in both versions
        // If depositAmt < 1 ether, no one can collect in either contract; we keep test wide so fuzzer may try values >= 1 ether

        // Advance time to exactly the unlockTime (block.timestamp == unlockTime)
        uint256 targetTime = block.timestamp + offset + 1;
        vm.warp(targetTime);

        // Try to Collect at exact unlock time. Catch revert/success to observe behavior.
        bool ok;
        vm.prank(actor);
        try c.Collect(withdrawAmt) {
            ok = true;
        } catch {
            ok = false;
        }

        // General invariant: In the reference contract, Collect must NOT succeed when called exactly at unlockTime (require block.timestamp > unlockTime).
        // Therefore assertTrue(!ok) must hold for all inputs when reference is used. The mutant that uses >= will allow ok==true for some inputs,
        // making this assertion fail on the mutant for those inputs.
        assertTrue(!ok);
    }
}

